using System;
using System.Collections.Generic;
using Framework.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// ParameterSetの登録、値管理、補正、
    /// イベント通知および破棄処理を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class ParameterSetTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// テスト用パラメーター識別子。
        /// </summary>
        private enum TestParameterId
        {
            /// <summary>
            /// 移動速度。
            /// </summary>
            MoveSpeed,

            /// <summary>
            /// 攻撃性。
            /// </summary>
            Aggression,

            /// <summary>
            /// 探索意欲。
            /// </summary>
            Exploration
        }

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestRegistration();
                TestRetrieval();
                TestValueChanges();
                TestModifiers();
                TestReset();
                TestEvents();
                TestIndependence();
                TestLifecycle();
                TestInvalidInput();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【ParameterSet テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 移動速度のテスト用定義を生成する。
        /// </summary>
        /// <returns>移動速度の定義</returns>
        private ParameterDefinition<TestParameterId>
            CreateSpeedDefinition()
        {
            return new ParameterDefinition<TestParameterId>(
                TestParameterId.MoveSpeed,
                4f,
                0f,
                10f);
        }

        /// <summary>
        /// 攻撃性のテスト用定義を生成する。
        /// </summary>
        /// <returns>攻撃性の定義</returns>
        private ParameterDefinition<TestParameterId>
            CreateAggressionDefinition()
        {
            return new ParameterDefinition<TestParameterId>(
                TestParameterId.Aggression,
                0.5f,
                0f,
                1f);
        }

        /// <summary>
        /// 標準的なテスト用パラメーター集合を生成する。
        /// </summary>
        /// <returns>2種類のパラメーターを登録した集合</returns>
        private ParameterSet<TestParameterId> CreateSet()
        {
            return new ParameterSet<TestParameterId>(
                new[]
                {
                    CreateSpeedDefinition(),
                    CreateAggressionDefinition()
                });
        }

        /// <summary>
        /// パラメーターの初期化と登録を検証する。
        /// </summary>
        private void TestRegistration()
        {
            using (var set = new ParameterSet<TestParameterId>())
            {
                bool emptyPassed =
                    set.Count == 0 && !set.HasParameters;
                Debug.Assert(emptyPassed, "空の集合の生成", this);
                Check(emptyPassed, "空の集合の生成");

                bool registerPassed =
                    set.TryRegister(CreateSpeedDefinition());
                Debug.Assert(registerPassed, "標準初期値での登録", this);
                Check(registerPassed, "標準初期値での登録");

                bool customPassed =
                    set.TryRegister(
                        CreateAggressionDefinition(),
                        0.8f);
                Debug.Assert(customPassed, "個体固有初期値での登録", this);
                Check(customPassed, "個体固有初期値での登録");

                bool countPassed =
                    set.Count == 2 && set.HasParameters;
                Debug.Assert(countPassed, "登録件数", this);
                Check(countPassed, "登録件数");

                bool duplicatePassed =
                    !set.TryRegister(CreateSpeedDefinition()) &&
                    set.Count == 2;
                Debug.Assert(duplicatePassed, "重複登録の拒否", this);
                Check(duplicatePassed, "重複登録の拒否");

                bool customValuePassed =
                    Mathf.Approximately(
                        set.GetValue(TestParameterId.Aggression),
                        0.8f);
                Debug.Assert(customValuePassed, "個体固有初期値の保持", this);
                Check(customValuePassed, "個体固有初期値の保持");
            }

            using (var set = CreateSet())
            {
                bool batchPassed = set.Count == 2;
                Debug.Assert(batchPassed, "定義一覧からの生成", this);
                Check(batchPassed, "定義一覧からの生成");
            }
        }

        /// <summary>
        /// パラメーターの検索と値の取得を検証する。
        /// </summary>
        private void TestRetrieval()
        {
            using (var set = CreateSet())
            {
                bool containsPassed =
                    set.Contains(TestParameterId.MoveSpeed) &&
                    !set.Contains(TestParameterId.Exploration);
                Debug.Assert(containsPassed, "登録状態の判定", this);
                Check(containsPassed, "登録状態の判定");

                bool getPassed =
                    set.GetParameter(
                        TestParameterId.MoveSpeed).Value == 4f;
                Debug.Assert(getPassed, "パラメーターの取得", this);
                Check(getPassed, "パラメーターの取得");

                bool tryGetPassed =
                    set.TryGetParameter(
                        TestParameterId.Aggression,
                        out var parameter) &&
                    parameter.Value == 0.5f;
                Debug.Assert(tryGetPassed, "安全なパラメーター取得", this);
                Check(tryGetPassed, "安全なパラメーター取得");

                bool missingPassed =
                    !set.TryGetParameter(
                        TestParameterId.Exploration,
                        out var missing) &&
                    missing == null;
                Debug.Assert(missingPassed, "未登録パラメーターの検索", this);
                Check(missingPassed, "未登録パラメーターの検索");

                bool valuePassed =
                    set.TryGetValue(
                        TestParameterId.MoveSpeed,
                        out float value) &&
                    value == 4f &&
                    !set.TryGetValue(
                        TestParameterId.Exploration,
                        out float missingValue) &&
                    missingValue == 0f;
                Debug.Assert(valuePassed, "最終値の安全な取得", this);
                Check(valuePassed, "最終値の安全な取得");

                bool normalizedPassed =
                    Mathf.Approximately(
                        set.GetNormalizedValue(
                            TestParameterId.MoveSpeed),
                        0.4f);
                Debug.Assert(normalizedPassed, "正規化値の取得", this);
                Check(normalizedPassed, "正規化値の取得");
            }
        }

        /// <summary>
        /// 基本値の変更と範囲制限を検証する。
        /// </summary>
        private void TestValueChanges()
        {
            using (var set = CreateSet())
            {
                bool changePassed =
                    set.SetBaseValue(
                        TestParameterId.MoveSpeed,
                        6f) &&
                    set.GetBaseValue(
                        TestParameterId.MoveSpeed) == 6f;
                Debug.Assert(changePassed, "基本値の変更", this);
                Check(changePassed, "基本値の変更");

                bool samePassed =
                    !set.SetBaseValue(
                        TestParameterId.MoveSpeed,
                        6f);
                Debug.Assert(samePassed, "同一基本値の変更省略", this);
                Check(samePassed, "同一基本値の変更省略");

                bool addPassed =
                    set.AddBaseValue(
                        TestParameterId.MoveSpeed,
                        2f) &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 8f;
                Debug.Assert(addPassed, "基本値への加算", this);
                Check(addPassed, "基本値への加算");

                bool clampPassed =
                    set.SetBaseValue(
                        TestParameterId.MoveSpeed,
                        100f) &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 10f;
                Debug.Assert(clampPassed, "基本値の範囲制限", this);
                Check(clampPassed, "基本値の範囲制限");
            }
        }

        /// <summary>
        /// 複数パラメーターの補正管理を検証する。
        /// </summary>
        private void TestModifiers()
        {
            using (var set = CreateSet())
            {
                // 補正元を識別するためのオブジェクト。
                object source = new object();

                var speedModifier =
                    ParameterModifier.CreateAdditive(
                        2f,
                        source);

                var aggressionModifier =
                    ParameterModifier.CreateAdditive(
                        0.25f,
                        source);

                bool addPassed =
                    set.TryAddModifier(
                        TestParameterId.MoveSpeed,
                        speedModifier) &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 6f;
                Debug.Assert(addPassed, "補正の追加", this);
                Check(addPassed, "補正の追加");

                bool duplicatePassed =
                    !set.TryAddModifier(
                        TestParameterId.MoveSpeed,
                        speedModifier);
                Debug.Assert(duplicatePassed, "補正の重複拒否", this);
                Check(duplicatePassed, "補正の重複拒否");

                bool missingPassed =
                    !set.TryAddModifier(
                        TestParameterId.Exploration,
                        speedModifier);
                Debug.Assert(missingPassed, "未登録対象への補正拒否", this);
                Check(missingPassed, "未登録対象への補正拒否");

                bool removePassed =
                    set.TryRemoveModifier(
                        TestParameterId.MoveSpeed,
                        speedModifier.Id) &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 4f;
                Debug.Assert(removePassed, "個別補正の解除", this);
                Check(removePassed, "個別補正の解除");

                set.TryAddModifier(
                    TestParameterId.MoveSpeed,
                    speedModifier);

                set.TryAddModifier(
                    TestParameterId.Aggression,
                    aggressionModifier);

                bool sourcePassed =
                    set.RemoveModifiersBySource(source) == 2 &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 4f &&
                    set.GetValue(
                        TestParameterId.Aggression) == 0.5f;
                Debug.Assert(sourcePassed, "補正元による全体解除", this);
                Check(sourcePassed, "補正元による全体解除");

                set.TryAddModifier(
                    TestParameterId.MoveSpeed,
                    speedModifier);

                set.TryAddModifier(
                    TestParameterId.Aggression,
                    aggressionModifier);

                bool clearPassed =
                    set.ClearModifiers() == 2 &&
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 4f &&
                    set.GetValue(
                        TestParameterId.Aggression) == 0.5f;
                Debug.Assert(clearPassed, "全補正の解除", this);
                Check(clearPassed, "全補正の解除");
            }
        }

        /// <summary>
        /// 個別および全体のリセットを検証する。
        /// </summary>
        private void TestReset()
        {
            using (var set = CreateSet())
            {
                set.SetBaseValue(
                    TestParameterId.MoveSpeed,
                    8f);

                set.SetBaseValue(
                    TestParameterId.Aggression,
                    0.9f);

                set.ResetParameter(
                    TestParameterId.MoveSpeed);

                bool singlePassed =
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 4f &&
                    Mathf.Approximately(
                        set.GetValue(TestParameterId.Aggression),
                        0.9f);
                Debug.Assert(singlePassed, "個別リセット", this);
                Check(singlePassed, "個別リセット");

                set.TryAddModifier(
                    TestParameterId.MoveSpeed,
                    ParameterModifier.CreateAdditive(2f));

                set.ResetAll();

                bool allPassed =
                    set.GetValue(
                        TestParameterId.MoveSpeed) == 4f &&
                    set.GetValue(
                        TestParameterId.Aggression) == 0.5f;
                Debug.Assert(allPassed, "全パラメーターのリセット", this);
                Check(allPassed, "全パラメーターのリセット");

                bool modifierPassed =
                    !set.GetParameter(
                        TestParameterId.MoveSpeed).HasModifiers;
                Debug.Assert(modifierPassed, "リセット時の補正解除", this);
                Check(modifierPassed, "リセット時の補正解除");
            }
        }

        /// <summary>
        /// 変更イベントと再入対策を検証する。
        /// </summary>
        private void TestEvents()
        {
            using (var set = CreateSet())
            {
                // イベント発生件数。
                int eventCount = 0;

                // 最後に通知された識別子。
                TestParameterId lastId =
                    TestParameterId.Exploration;

                // 最後に通知された変更前後の値。
                float previousValue = 0f;
                float newValue = 0f;

                // 通知時に状態が更新済みかどうか。
                bool stateUpdated = false;

                Action<TestParameterId, float, float> handler =
                    (id, previous, current) =>
                    {
                        eventCount++;
                        lastId = id;
                        previousValue = previous;
                        newValue = current;

                        stateUpdated =
                            set.GetValue(id) == current;
                    };

                set.ValueChanged += handler;

                try
                {
                    set.SetBaseValue(
                        TestParameterId.MoveSpeed,
                        6f);

                    bool countPassed = eventCount == 1;
                    Debug.Assert(countPassed, "集合の変更イベント", this);
                    Check(countPassed, "集合の変更イベント");

                    bool argumentsPassed =
                        lastId == TestParameterId.MoveSpeed &&
                        previousValue == 4f &&
                        newValue == 6f &&
                        stateUpdated;
                    Debug.Assert(argumentsPassed, "イベント引数と状態", this);
                    Check(argumentsPassed, "イベント引数と状態");

                    set.SetBaseValue(
                        TestParameterId.MoveSpeed,
                        6f);

                    bool unchangedPassed = eventCount == 1;
                    Debug.Assert(unchangedPassed, "値不変時の通知省略", this);
                    Check(unchangedPassed, "値不変時の通知省略");

                    // 通知中の登録解除が拒否されるか確認する。
                    bool reentryRejected = false;

                    Action<TestParameterId, float, float>
                        reentryHandler = (id, previous, current) =>
                        {
                            reentryRejected =
                                Throws<InvalidOperationException>(
                                    () => set.TryUnregister(id));
                        };

                    set.ValueChanged += reentryHandler;

                    try
                    {
                        set.SetBaseValue(
                            TestParameterId.MoveSpeed,
                            7f);
                    }
                    finally
                    {
                        set.ValueChanged -= reentryHandler;
                    }

                    Debug.Assert(reentryRejected, "通知中の再入防止", this);
                    Check(reentryRejected, "通知中の再入防止");
                }
                finally
                {
                    set.ValueChanged -= handler;
                }

                int beforeUnsubscribe = eventCount;

                set.SetBaseValue(
                    TestParameterId.MoveSpeed,
                    8f);

                bool unsubscribePassed =
                    eventCount == beforeUnsubscribe;
                Debug.Assert(unsubscribePassed, "イベントの購読解除", this);
                Check(unsubscribePassed, "イベントの購読解除");
            }
        }

        /// <summary>
        /// 個体ごとの状態が独立していることを検証する。
        /// </summary>
        private void TestIndependence()
        {
            // 共通定義を複数の個体で共有する。
            var definition = CreateSpeedDefinition();

            using (var first = new ParameterSet<TestParameterId>())
            using (var second = new ParameterSet<TestParameterId>())
            {
                first.TryRegister(definition);
                second.TryRegister(definition);

                first.SetBaseValue(
                    TestParameterId.MoveSpeed,
                    7f);

                bool valuePassed =
                    first.GetValue(
                        TestParameterId.MoveSpeed) == 7f &&
                    second.GetValue(
                        TestParameterId.MoveSpeed) == 4f;
                Debug.Assert(valuePassed, "個体別の値管理", this);
                Check(valuePassed, "個体別の値管理");

                first.TryAddModifier(
                    TestParameterId.MoveSpeed,
                    ParameterModifier.CreateAdditive(2f));

                bool modifierPassed =
                    first.GetValue(
                        TestParameterId.MoveSpeed) == 9f &&
                    second.GetValue(
                        TestParameterId.MoveSpeed) == 4f;
                Debug.Assert(modifierPassed, "個体別の補正管理", this);
                Check(modifierPassed, "個体別の補正管理");
            }
        }

        /// <summary>
        /// 登録解除、消去および破棄処理を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            using (var set = CreateSet())
            {
                // 登録解除後も参照を保持して通知の解除を確認する。
                var parameter =
                    set.GetParameter(TestParameterId.MoveSpeed);

                int eventCount = 0;

                set.ValueChanged +=
                    (id, previous, current) => eventCount++;

                bool removePassed =
                    set.TryUnregister(
                        TestParameterId.MoveSpeed) &&
                    set.Count == 1 &&
                    !set.Contains(TestParameterId.MoveSpeed);
                Debug.Assert(removePassed, "パラメーターの登録解除", this);
                Check(removePassed, "パラメーターの登録解除");

                parameter.SetBaseValue(8f);

                bool detachPassed = eventCount == 0;
                Debug.Assert(detachPassed, "登録解除後の通知切断", this);
                Check(detachPassed, "登録解除後の通知切断");

                set.Clear();

                bool clearPassed =
                    set.Count == 0 &&
                    !set.HasParameters;
                Debug.Assert(clearPassed, "全登録の解除", this);
                Check(clearPassed, "全登録の解除");

                set.Dispose();

                // 複数回の破棄が安全であることを確認する。
                set.Dispose();

                bool disposePassed =
                    set.IsDisposed &&
                    Throws<ObjectDisposedException>(() =>
                    {
                        set.GetValue(TestParameterId.MoveSpeed);
                    });
                Debug.Assert(disposePassed, "破棄後の操作拒否", this);
                Check(disposePassed, "破棄後の操作拒否");
            }
        }

        /// <summary>
        /// 不正な引数と未登録識別子の処理を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            using (var set = CreateSet())
            {
                bool nullPassed =
                    Throws<ArgumentNullException>(() =>
                    {
                        set.TryRegister(null);
                    });
                Debug.Assert(nullPassed, "null定義の拒否", this);
                Check(nullPassed, "null定義の拒否");

                bool missingPassed =
                    Throws<KeyNotFoundException>(() =>
                    {
                        set.GetValue(TestParameterId.Exploration);
                    });
                Debug.Assert(missingPassed, "未登録識別子の直接取得拒否", this);
                Check(missingPassed, "未登録識別子の直接取得拒否");
            }

            bool duplicatePassed =
                Throws<ArgumentException>(() =>
                {
                    using (var set =
                        new ParameterSet<TestParameterId>(
                            new[]
                            {
                                CreateSpeedDefinition(),
                                CreateSpeedDefinition()
                            }))
                    {
                    }
                });
            Debug.Assert(duplicatePassed, "重複定義一覧の拒否", this);
            Check(duplicatePassed, "重複定義一覧の拒否");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
